etapas.css:
/* 1. RESET E CONFIGURAÇÕES GLOBAIS */
* {
  [[s:e1_c1|margem externa]]
  [[s:e1_c2|preenchimento interno]]
  [[s:e1_c3|modelo de caixa]]
}
body {
  [[s:e1_c4|família da fonte]]
  [[s:e1_c5|cor de fundo]]
  [[s:e1_c6|cor do texto]]
  line-height: 1.6;
}
.container {
  [[s:e1_c7|largura fixa]]
  [[s:e1_c8|centralização]]
  padding: 20px 0;
}

/* 2. CABEÇALHO COM FLEXBOX */
.cabecalho {
  [[s:e2_c1|ativar flexbox]]
  [[s:e2_c2|distribuir nos extremos]]
  [[s:e2_c3|alinhar na vertical]]
  background-color: #0f1412;
  padding: 15px 50px;
  [[s:e2_c4|borda inferior verde]]
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.7);
}
.logo {
  [[s:e2_c5|ativar flexbox]]
  [[s:e2_c6|alinhar na vertical]]
  gap: 15px;
}
.logo-img {
  width: 72px;
  height: 72px;
  [[s:e2_c7|formato de círculo]]
  [[s:e2_c8|esconder o excesso]]
  border: 3px solid #d62283;
}
.logo-img img {
  width: 100%;
  height: 100%;
  [[s:e2_c9|preencher sem distorcer]]
  display: block;
}
.logo h1 {
  font-size: 24px;
  letter-spacing: 2px;
  color: #ffffff;
}

/* 3. MENU EM CASCATA (DROPDOWN) */
.menu-principal {
  [[s:e3_c1|ativar flexbox]]
  align-items: center;
  [[s:e3_c2|espaço entre itens]]
  [[s:e3_c3|remover marcadores]]
}
.menu-principal > li > a {
  color: #f1f2f6;
  text-decoration: none;
  font-size: 15px;
  font-weight: 500;
  transition: color 0.3s;
}
.menu-principal > li > a:hover {
  color: #d62283;
}
.dropdown {
  [[s:e3_c4|referência de posição]]
}
.submenu {
  [[s:e3_c5|oculto por padrão]]
  [[s:e3_c6|flutuar sobre a página]]
  top: 100%;
  left: 0;
  background-color: #0f1412;
  list-style: none;
  min-width: 190px;
  border-radius: 6px;
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.7);
  border: 1px solid #0f4d34;
  padding: 10px 0;
  z-index: 100;
}
[[s:e3_s1|seletor do hover]] {
  [[s:e3_c7|exibir o submenu]]
}
.submenu li a {
  display: block;
  padding: 10px 18px;
  color: #dfe4ea;
  text-decoration: none;
  font-size: 14px;
  transition: background-color 0.2s, padding-left 0.2s;
}
.submenu li a:hover {
  background-color: #d62283;
  color: #ffffff;
  padding-left: 24px;
}

/* 4. SEÇÃO HERO COM FLEXBOX */
.hero {
  [[s:e4_c1|ativar flexbox]]
  [[s:e4_c2|alinhar na vertical]]
  [[s:e4_c3|distribuir nos extremos]]
  [[s:e4_c4|espaço entre texto e imagem]]
  background-color: #0e1211;
  border-radius: 12px;
  padding: 40px;
  margin: 30px 0 50px 0;
  border: 1px solid #143d2c;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
}
.hero-texto {
  [[s:e4_c5|proporção do texto]]
}
.tag {
  display: inline-block;
  background-color: rgba(214, 34, 131, 0.15);
  color: #e01a88;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 20px;
  margin-bottom: 15px;
  border: 1px solid rgba(214, 34, 131, 0.4);
}
.hero-texto h2 {
  font-size: 32px;
  line-height: 1.2;
  margin-bottom: 15px;
  color: #ffffff;
}
.hero-texto p {
  color: #95a5a6;
  font-size: 15px;
  margin-bottom: 25px;
}
.btn {
  display: inline-block;
  [[s:e4_c6|fundo magenta]]
  color: #ffffff;
  [[s:e4_c7|remover sublinhado]]
  font-weight: 600;
  font-size: 14px;
  padding: 12px 28px;
  border-radius: 6px;
  transition: background-color 0.3s, transform 0.2s;
}
.btn:hover {
  background-color: #b5156c;
  transform: translateY(-2px);
}
.hero-img {
  [[s:e4_c8|proporção da imagem]]
  [[s:e4_c9|altura do banner]]
  overflow: hidden;
  border-radius: 10px;
  border: 2px solid #0f4d34;
}
.hero-img img {
  width: 100%;
  height: 100%;
  [[s:e4_c10|preencher sem distorcer]]
  display: block;
}

/* 5. TÍTULOS DE SEÇÃO + PERSONAGENS COM CSS GRID */
.titulo-secao {
  [[s:e5_c1|centralizar o texto]]
  margin-bottom: 35px;
}
.titulo-secao h2 {
  font-size: 28px;
  color: #ffffff;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.titulo-secao p {
  color: #95a5a6;
  font-size: 15px;
}
.secao-personagens {
  margin-bottom: 60px;
}
.grid-personagens {
  [[s:e5_c2|ativar grid]]
  [[s:e5_c3|colunas da grade]]
  [[s:e5_c4|espaço entre os cards]]
}
.card {
  background-color: #0e1211;
  border-radius: 10px;
  [[s:e5_c5|esconder o excesso]]
  border: 1px solid #143d2c;
  transition: transform 0.3s, border-color 0.3s, box-shadow 0.3s;
}
.card:hover {
  [[s:e5_c6|subir o card]]
  border-color: #d62283;
  box-shadow: 0 12px 20px rgba(214, 34, 131, 0.25);
}
.card-img {
  width: 100%;
  [[s:e5_c7|altura da imagem]]
  overflow: hidden;
}
[[s:e5_s1|seletor das imagens dos cards]] {
  width: 100%;
  height: 100%;
  [[s:e5_c8|preencher sem distorcer]]
  [[s:e5_c9|foco do corte]]
  display: block;
  transition: transform 0.4s ease;
}
.card:hover .card-img img {
  transform: scale(1.08);
}
.card-info {
  padding: 18px;
}
.estilo {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 4px;
  margin-bottom: 10px;
}
.agua { background-color: #0b3d26; color: #6fe3a5; }
.kekkijutsu { background-color: #590d34; color: #ff66b2; }
.trovao { background-color: #1a2e1d; color: #f7d070; }
.feras { background-color: #0e3020; color: #8ce4b5; }
.card-info h3 {
  font-size: 18px;
  margin-bottom: 8px;
  color: #ffffff;
}
.card-info p {
  color: #95a5a6;
  font-size: 13px;
  line-height: 1.5;
}

/* 6. SEÇÃO DE TRADIÇÕES COM FLEXBOX */
.secao-info {
  margin-bottom: 60px;
}
.flex-info {
  [[s:e6_c1|ativar flexbox]]
  [[s:e6_c2|espaço entre as caixas]]
}
.box-info {
  [[s:e6_c3|dividir igualmente]]
  background-color: #0e1211;
  padding: 25px;
  border-radius: 10px;
  border: 1px solid #143d2c;
  [[s:e6_c4|faixa superior verde]]
  box-shadow: 0 6px 15px rgba(0, 0, 0, 0.4);
}
.box-info h4 {
  font-size: 18px;
  color: #ffffff;
  margin-bottom: 12px;
}
.box-info p {
  font-size: 14px;
  color: #95a5a6;
}

/* 7. RODAPÉ COM FLEXBOX */
.rodape {
  [[s:e7_c1|ativar flexbox]]
  [[s:e7_c2|direção em coluna]]
  [[s:e7_c3|centralizar na horizontal]]
  [[s:e7_c4|centralizar na vertical]]
  gap: 8px;
  background-color: #08090b;
  padding: 30px 20px;
  [[s:e7_c5|borda superior verde]]
  color: #718093;
  font-size: 14px;
}
.rodape strong {
  color: #d62283;
}

