solucao.css/style.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: Arial, sans-serif;
  background-color: #f4f6fb;
  color: #1a2233;
}
.topo {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 40px;
  background-color: #14213d;
}
.logo {
  color: #ffffff;
  font-size: 22px;
}
.menu {
  display: flex;
  gap: 24px;
  list-style: none;
}
.menu a {
  color: #ffffff;
  text-decoration: none;
}
.container {
  width: 960px;
  margin: 0 auto;
}
#sobre {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 40px 0;
}
.foto {
  width: 160px;
  height: 160px;
  border-radius: 50%;
}
#projetos h2 {
  margin-bottom: 16px;
}
.grade {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.card {
  background-color: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  transition: transform 0.3s;
}
.card img {
  width: 100%;
  display: block;
}
.card h3 {
  padding: 12px;
  font-size: 16px;
}
.card:hover {
  transform: translateY(-6px);
}
.rodape {
  margin-top: 40px;
  padding: 24px;
  text-align: center;
  background-color: #14213d;
  color: #ffffff;
}
